=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters.
// Implements interface_spec.md and microarchitecture.md (rr_arbiter).
//
// State: one priority pointer `ptr` ($clog2(N) bits), reset to 0.
// Grant: combinational. The winner is the first requester with req high at
// or after ptr, searching upwards and wrapping from N-1 to 0.
// Update: on a rising edge with a grant, ptr moves to one past the winner,
// wrapping explicitly at N (not at a power of two). With no request ptr
// holds. During reset grant still follows req, and ptr goes to 0.
module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);

    localparam integer PW = (N > 1) ? $clog2(N) : 1;

    reg [PW-1:0] ptr;
    reg [PW-1:0] ptr_nxt;
    reg          found;
    integer      j;
    integer      jn;

    // Grant search, as two passes with constant indices:
    //   pass 1: requesters j >= ptr, lowest first
    //   pass 2: if none, requesters from 0 upwards (all of them are < ptr)
    // Together they give the first requester at or after ptr, wrapping at N.
    // Every variable gets a default first, so no latch is inferred.
    always @* begin
        grant   = {N{1'b0}};
        ptr_nxt = ptr;
        found   = 1'b0;
        jn      = 0;
        for (j = 0; j < N; j = j + 1) begin
            if (!found && req[j] && (j[PW-1:0] >= ptr)) begin
                found    = 1'b1;
                grant[j] = 1'b1;
                jn       = j + 1;
                if (jn == N) ptr_nxt = {PW{1'b0}};
                else         ptr_nxt = jn[PW-1:0];
            end
        end
        for (j = 0; j < N; j = j + 1) begin
            if (!found && req[j]) begin
                found    = 1'b1;
                grant[j] = 1'b1;
                jn       = j + 1;
                if (jn == N) ptr_nxt = {PW{1'b0}};
                else         ptr_nxt = jn[PW-1:0];
            end
        end
    end

    // Pointer register: synchronous active-low reset to 0, otherwise the update.
    always @(posedge clk) begin
        if (!rst_n) ptr <= {PW{1'b0}};
        else        ptr <= ptr_nxt;
    end

`ifdef FORMAL
    // Design-intent properties (interface_spec.md section 6).
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) if (!f_past_valid) assume (!rst_n);

    // Circular distance from a_from up to a_to, modulo N.
    function integer f_dist(input integer a_from, input integer a_to);
        f_dist = (a_to >= a_from) ? (a_to - a_from) : (a_to + N - a_from);
    endfunction

    integer f_win;
    integer fw;
    always @(*) begin
        f_win = -1;
        for (fw = N - 1; fw >= 0; fw = fw - 1)
            if (grant[fw]) f_win = fw;
    end

    integer fm;
    always @(*) begin
        // One-hot or zero.
        assert ((grant & (grant - 1'b1)) == {N{1'b0}});
        // Only to a requester.
        assert ((grant & ~req) == {N{1'b0}});
        // Work conserving.
        assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
        if (f_past_valid) begin
            // Pointer in range.
            assert (ptr < N);
            // No requester sits between the pointer and the winner.
            if (grant != {N{1'b0}})
                for (fm = 0; fm < N; fm = fm + 1)
                    if (req[fm] && (fm != f_win))
                        assert (f_dist(ptr, fm) > f_dist(ptr, f_win));
        end
    end

    // Pointer update rule.
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert (ptr == {PW{1'b0}});
            else if ($past(grant) != {N{1'b0}})
                assert (ptr == (($past(f_win) == N - 1) ? 0 : ($past(f_win) + 1)));
            else
                assert (ptr == $past(ptr));
        end
    end

    // Wait bound: a held request waits at most N-1 cycles.
    genvar gi;
    generate
        for (gi = 0; gi < N; gi = gi + 1) begin : g_fair
            reg [31:0] f_wait = 32'd0;
            always @(posedge clk) begin
                if (!rst_n)                     f_wait <= 32'd0;
                else if (req[gi] && !grant[gi]) f_wait <= f_wait + 32'd1;
                else                            f_wait <= 32'd0;
            end
            always @(*) begin
                assert (f_wait <= N - 1);
                if (f_past_valid && (f_wait != 32'd0))
                    assert (f_wait + f_dist(ptr, gi) <= N - 1);
                cover (grant[gi]);
                cover (f_wait == N - 1);
            end
        end
    endgenerate

    always @(*) cover (req == {N{1'b1}});
    always @(posedge clk)
        if (f_past_valid)
            cover ($past(rst_n) && ($past(ptr) == N - 1) && (ptr == {PW{1'b0}}));
`endif

endmodule
=== END FILE ===
