// Self-checking testbench for rr_arbiter, run at N=4 and N=5 side by side.
// Each cycle: inputs are driven on the falling edge, grant is checked against
// a reference pointer model, then the model advances on the rising edge.
module rr_arbiter_tb;

    reg            clk;
    reg            rst_n;
    reg  [7:0]     stim;
    wire [3:0]     req4 = stim[3:0];
    wire [4:0]     req5 = stim[4:0];
    wire [3:0]     grant4;
    wire [4:0]     grant5;

    rr_arbiter #(.N(4)) dut4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) dut5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    integer        passed;
    integer        failed;
    integer        cyc;
    integer        rc;
    integer        k;
    integer        d;
    integer        ptr_m       [0:1];
    integer        waitc       [0:15];
    integer        rot_cnt     [0:1];
    integer        cov_none    [0:1];
    integer        cov_alone   [0:15];
    integer        cov_all     [0:1];
    integer        cov_held    [0:1];
    integer        cov_maxwait [0:1];
    integer        cov_rst     [0:1];
    integer        cov_rot     [0:1];
    reg  [7:0]     prev_r      [0:1];
    reg            seen_release;
    reg  [15:0]    lfsr;
    reg  [8*64-1:0] nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    // Reference: first requester with r set at or after p, wrapping at n.
    // Returns -1 when nothing is requested.
    function integer winner_of;
        input [7:0]   r;
        input integer p;
        input integer n;
        integer kk;
        integer idx;
        begin
            winner_of = -1;
            for (kk = n - 1; kk >= 0; kk = kk - 1) begin
                idx = (p + kk) % n;
                if (r[idx]) winner_of = idx;
            end
        end
    endfunction

    task fail_cov(input integer n, input integer id, input integer count);
        // id: 1 none, 2 all, 3 held among changing, 4 wait N-1,
        //     5 reset during traffic, 6 rotation after reset, 10+i alone i
        begin
            if (count > 0) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d: coverage goal %0d never reached", n, id);
            end
        end
    endtask

    task check(input integer dd, input integer n, input [7:0] r, input [7:0] g);
        integer   w;
        integer   j;
        integer   prevw;
        reg [7:0] eg;
        reg [7:0] mask;
        begin
            mask = (8'd1 << n) - 8'd1;
            // Grant against the reference pointer model.
            w = winner_of(r, ptr_m[dd], n);
            if (w >= 0) eg = 8'd1 << w;
            else        eg = 8'd0;
            if (g === eg) passed = passed + 1;
            else begin
                failed = failed + 1;
                $error("N=%0d cycle %0d: req %b ptr %0d grant %b, expected %b",
                       n, cyc, r, ptr_m[dd], g, eg);
            end
            // Fairness: a held request waits at most N-1 cycles.
            for (j = 0; j < n; j = j + 1) begin
                prevw = waitc[dd*8+j];
                if (rst_n && r[j] && (prevw > 0) &&
                    (((r ^ prev_r[dd]) & mask & ~(8'd1 << j)) != 8'd0))
                    cov_held[dd] = cov_held[dd] + 1;
                if (!rst_n) waitc[dd*8+j] = 0;
                else if (r[j] && !g[j]) begin
                    waitc[dd*8+j] = prevw + 1;
                    if (waitc[dd*8+j] <= n - 1) passed = passed + 1;
                    else begin
                        failed = failed + 1;
                        $error("N=%0d cycle %0d: requester %0d has waited %0d cycles",
                               n, cyc, j, waitc[dd*8+j]);
                    end
                    if (waitc[dd*8+j] == n - 1) cov_maxwait[dd] = cov_maxwait[dd] + 1;
                end else waitc[dd*8+j] = 0;
            end
            // Coverage.
            if (rst_n && ((r & mask) == 8'd0)) cov_none[dd] = cov_none[dd] + 1;
            if (rst_n && ((r & mask) == mask)) cov_all[dd] = cov_all[dd] + 1;
            if (rst_n)
                for (j = 0; j < n; j = j + 1)
                    if ((r & mask) == (8'd1 << j)) cov_alone[dd*8+j] = cov_alone[dd*8+j] + 1;
            if (!rst_n && seen_release && ((r & mask) != 8'd0)) cov_rst[dd] = cov_rst[dd] + 1;
            // Strict rotation 0,1,..,N-1,0,.. with everyone requesting after reset.
            if (!rst_n) rot_cnt[dd] = 0;
            else if (rot_cnt[dd] >= 0) begin
                if (((r & mask) == mask) && (g === (8'd1 << (rot_cnt[dd] % n)))) begin
                    rot_cnt[dd] = rot_cnt[dd] + 1;
                    if (rot_cnt[dd] == 2 * n) cov_rot[dd] = cov_rot[dd] + 1;
                end else rot_cnt[dd] = -1;
            end
            prev_r[dd] = r & mask;
        end
    endtask

    task advance(input integer dd, input integer n, input [7:0] r);
        integer w;
        begin
            if (!rst_n) ptr_m[dd] = 0;
            else begin
                w = winner_of(r, ptr_m[dd], n);
                if (w >= 0) ptr_m[dd] = (w + 1) % n;
            end
        end
    endtask

    task step(input rst, input [7:0] s);
        begin
            @(negedge clk);
            rst_n = rst;
            stim  = s;
            #1;
            cyc = cyc + 1;
            check(0, 4, {4'd0, req4}, {4'd0, grant4});
            check(1, 5, {3'd0, req5}, {3'd0, grant5});
            @(posedge clk);
            advance(0, 4, {4'd0, req4});
            advance(1, 5, {3'd0, req5});
            if (rst) seen_release = 1'b1;
        end
    endtask

    task lfsr_next;
        begin
            lfsr = {lfsr[14:0], lfsr[15] ^ lfsr[13] ^ lfsr[12] ^ lfsr[10]};
        end
    endtask

    initial begin
        passed       = 0;
        failed       = 0;
        cyc          = 0;
        rc           = 0;
        seen_release = 1'b0;
        rst_n        = 1'b0;
        stim         = 8'h00;
        lfsr         = 16'hACE1;
        nonce        = {64{8'h00}};
        for (k = 0; k < 2; k = k + 1) begin
            ptr_m[k]       = 0;
            rot_cnt[k]     = -1;
            cov_none[k]    = 0;
            cov_all[k]     = 0;
            cov_held[k]    = 0;
            cov_maxwait[k] = 0;
            cov_rst[k]     = 0;
            cov_rot[k]     = 0;
            prev_r[k]      = 8'h00;
        end
        for (k = 0; k < 16; k = k + 1) begin
            waitc[k]     = 0;
            cov_alone[k] = 0;
        end

        // 1. Power-on reset; grant follows req during reset from ptr 0.
        step(1'b0, 8'h00);
        step(1'b0, 8'h00);
        step(1'b0, 8'h1F);
        step(1'b0, 8'h00);
        // 2. No requests.
        step(1'b1, 8'h00);
        step(1'b1, 8'h00);
        // 3. Each requester alone.
        for (k = 0; k < 5; k = k + 1) begin
            step(1'b1, 8'd1 << k);
            step(1'b1, 8'd1 << k);
        end
        // 4. Reset, then everyone requesting: strict rotation from 0,
        //    and every requester waits the longest fair wait (N-1).
        step(1'b0, 8'h00);
        for (k = 0; k < 20; k = k + 1) step(1'b1, 8'h1F);
        // 5. A held request among changing others: requester 2, then requester 0.
        for (k = 0; k < 40; k = k + 1) begin
            lfsr_next;
            step(1'b1, (lfsr[7:0] & 8'h1F) | 8'h04);
        end
        for (k = 0; k < 40; k = k + 1) begin
            lfsr_next;
            step(1'b1, (lfsr[7:0] & 8'h1F) | 8'h01);
        end
        // 6. Random subsets, with requests dropped and raised again.
        for (k = 0; k < 200; k = k + 1) begin
            lfsr_next;
            step(1'b1, lfsr[7:0] & 8'h1F);
        end
        // 7. Reset during traffic, mid-rotation, then rotation from 0 again.
        for (k = 0; k < 7; k = k + 1) step(1'b1, 8'h1F);
        step(1'b0, 8'h1F);
        step(1'b0, 8'h1B);
        for (k = 0; k < 20; k = k + 1) step(1'b1, 8'h1F);
        // 8. Quiet end.
        step(1'b1, 8'h00);
        step(1'b1, 8'h00);

        // Coverage goals, for each instance.
        for (d = 0; d < 2; d = d + 1) begin
            fail_cov(4 + d, 1, cov_none[d]);
            fail_cov(4 + d, 2, cov_all[d]);
            fail_cov(4 + d, 3, cov_held[d]);
            fail_cov(4 + d, 4, cov_maxwait[d]);
            fail_cov(4 + d, 5, cov_rst[d]);
            fail_cov(4 + d, 6, cov_rot[d]);
            for (k = 0; k < 4 + d; k = k + 1)
                fail_cov(4 + d, 10 + k, cov_alone[d*8+k]);
        end

        rc = $value$plusargs("nirmaan_nonce=%s", nonce);
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule
=== END FILE ===
